-- Human-readable dates next to the epoch-day and epoch-millis columns the app writes. These are
-- generated by Postgres and never sent by the app; handy in the Table Editor and for SQL.
alter table public.holidays add column date date generated always as (date '1970-01-01' + epoch_day::int) stored;
alter table public.periods  add column start_date date generated always as (date '1970-01-01' + start_epoch_day::int) stored;
alter table public.periods  add column end_date   date generated always as (date '1970-01-01' + end_epoch_day::int) stored;
alter table public.entries  add column clock_in_at  timestamptz generated always as (to_timestamp(clock_in / 1000.0)) stored;
alter table public.entries  add column clock_out_at timestamptz generated always as (to_timestamp(clock_out / 1000.0)) stored;
alter table public.entries  add column deleted      boolean generated always as (deleted_at is not null) stored;
alter table public.holidays add column deleted      boolean generated always as (deleted_at is not null) stored;
alter table public.periods  add column deleted      boolean generated always as (deleted_at is not null) stored;
